package com.hoteluq;
import com.hoteluq.model.*;import com.hoteluq.model.enums.*;import com.hoteluq.pattern.behavioral.strategy.*;import com.hoteluq.pattern.creational.RoomFactory;import com.hoteluq.service.PointsService;import org.junit.jupiter.api.Test;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class HotelRulesTest {@Test void roomFactoryCreatesSuite(){Room r=new RoomFactory().create(RoomType.SUITE,"9");assertEquals(420000,r.getPricePerNight());}@Test void walletRejectsInsufficientBalance(){Wallet w=new Wallet();assertThrows(IllegalStateException.class,()->w.charge(100,"test"));}@Test void pointsExpireAfterOneYear(){PointsAccount a=new PointsAccount();a.earn(100,LocalDate.of(2025,1,1));assertEquals(0,a.available(LocalDate.of(2026,1,1)));}@Test void pointsRedeemSoonestExpiryFirst(){PointsAccount a=new PointsAccount();a.earn(100,LocalDate.of(2025,5,1));a.earn(200,LocalDate.of(2025,8,1));a.redeem(120,LocalDate.of(2025,9,1));assertEquals(180,a.available(LocalDate.of(2025,9,1)));}@Test void cancellationPolicyUses80PercentBetween24And72Hours(){var p=new StandardCancellationPolicy();assertEquals(80,p.refund(100,LocalDateTime.now().plusHours(48),LocalDateTime.now()),0.01);}@Test void invalidReservationDatesAreRejected(){User u=new User("A","a@b.com",Role.CLIENT);Room r=new RoomFactory().create(RoomType.STANDARD,"1");assertThrows(IllegalArgumentException.class,()->new Reservation(u,r,LocalDate.now(),LocalDate.now(),java.util.List.of(),100));}}
